---
applyTo: "src/common/**/*.{ts,tsx}"
---

# Core Common Utilities Instructions

## Healthcare Common Files

### Permission System (`Permissions.tsx`)
- Role-based access control for medical staff (Doctor, Nurse, Admin)
- Dynamic permission checking with `getPermissions()` function
- Emergency override permissions for critical care situations

### Application Constants (`constants.tsx`)  
- Core application configuration
- `RESULTS_PER_PAGE_LIMIT` for API pagination
- `LocalStorageKeys` for secure browser storage

### Validation Utilities (`validation.tsx`)
- Form validation schemas using `zod`
- Healthcare system password and identifier validation

## Implementation Patterns

### Medical Permission Checking
```typescript
// Role-based permission example
export const canAccessPatientData = (user: UserRead, patientId: string) => {
  return (
    hasPermission(user, "view_patient") ||
    isAssignedToPatient(user, patientId) ||
    isEmergencyOverride(user)
  );
};
```

### Form Validation
```typescript
// Vital signs validation example
export const validateVitalSigns = (vitals: VitalSigns) => {
  const schema = z.object({
    temperature: z.number().min(95).max(110),
    heartRate: z.number().min(30).max(200),
    bloodPressure: z.object({
      systolic: z.number().min(60).max(250),
      diastolic: z.number().min(40).max(150),
    }),
  });
  return schema.safeParse(vitals);
};
```
---
applyTo: "src/components/**/*.{ts,tsx}"
---

# React Components Instructions

## Import Path Conventions
- Use path aliases: `@/components/`, `@/types/`, `@/lib/`, `@/pages/`
- Import order: External packages → `@/components/ui/` → `@/components/` → `@/CAREUI/` → `@/types/` → `@/lib/` → relative imports
- Use named exports from `lucide-react` for icons (e.g., `import { SettingsIcon } from "lucide-react"`)
- Import `useTranslation` from `react-i18next` for internationalization

## Component Architecture Patterns
- Healthcare domain: Feature-based organization - Components grouped by Patient/, Facility/, Medication/, etc.
- React 19.1.1 hooks: Functional components only - Use React 19.1.1 hooks pattern
- TypeScript interfaces: Props interfaces - Always define PatientInfoCardProps, etc.
- Handle prefix: Event handlers - handleSubmit, handleTagsUpdate, handlePatientSelect

## UI Component System
- shadcn/ui components: Primary UI - Button, Card, Badge, etc. from `@/components/ui/`
- Healthcare-specific: CAREUI custom - Calendar, WeekdayCheckbox, Zoom from `@/CAREUI/`
- Button variants: Use `buttonVariants` from `@/components/ui/button` with CVA patterns
- Card structure: Follow `<Card><CardHeader>` pattern for consistent layouts

## Healthcare-Specific Patterns
- Patient data: Use `PatientRead` type from `@/types/emr/patient/patient`
- Tag system: Implement `TagAssignmentSheet` with `TagEntityType` for patient/facility tags
- Hover cards: Use `PatientHoverCard` for patient info overlays
- Badge usage: Display patient status, facility capacity, medication dosage with color variants

## Styling with Tailwind CSS 4.1.3
- Class variance authority: Use `cva()` for variant-based component styling
- Utility function: Use `cn()` from `@/lib/utils` for conditional classes
- Color system: Follow primary-700, gray-900, red-500 pattern with dark mode variants
- Shadow system: Use shadow-sm, shadow-xs for elevation
- Focus states: Include `focus-visible:ring-1` and `focus-visible:outline-hidden`

## State Management Integration
- Server state: React Query - Use `@tanstack/react-query` for facility data, patient records
- UI state: Local state - useState for UI state, useCallback for event handlers
- Controlled inputs: Form state - Handle controlled inputs with proper TypeScript typing
- Async operations: Loading states - Implement loading, error, and success states

## Internationalization (i18n)
- Translation hook: Use `const { t } = useTranslation()` pattern
- Text content: Wrap all user-facing text in `t("key.path")`
- Healthcare terminology: Use consistent medical term translations
- Date formatting: Use `date-fns` with locale support for medical timestamps

## Accessibility for Healthcare
- ARIA labels: Critical for medical data (patient names, vital signs, medication alerts)
- Keyboard navigation: Essential for clinical workflows and emergency situations
- Screen reader support: Proper heading hierarchy for medical records
- Color contrast: Meet WCAG AA standards for clinical environmentsimport { ChevronsUpDown, Hospital, LayoutDashboard } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { useAppSidebar } from "@/components/ui/sidebar/app-sidebar-provider";
import { cn } from "@/lib/utils";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useSidebar } from "@/components/ui/sidebar";

import { FacilityBareMinimum } from "@/types/facility/facility";

export function FacilitySwitcher({
  facilities,
  selectedFacility,
}: {
  facilities: FacilityBareMinimum[];
  selectedFacility: FacilityBareMinimum | null;
}) {
  const { isMobile, setOpenMobile } = useSidebar();
  const { handleMenuOpenChange } = useAppSidebar();
  const { t } = useTranslation();

  return (
    <DropdownMenu onOpenChange={handleMenuOpenChange}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className="h-9 max-w-full gap-2 rounded-lg border-neutral-300 bg-white px-3 text-sm font-normal text-neutral-950 shadow-sm hover:bg-neutral-100 focus-visible:ring-indigo-400"
          aria-label={selectedFacility?.name || t("select_facility")}
        >
          {
            <>
              <div className="grid min-w-0 flex-1 text-left text-sm leading-tight">
                <span className="truncate font-normal">
                  {selectedFacility?.name || t("select_facility")}
                </span>
              </div>
              <ChevronsUpDown className="ml-auto size-4 shrink-0 text-neutral-500" />
            </>
          }
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        className="w-(--radix-dropdown-menu-trigger-width) min-w-56 rounded-lg max-h-screen overflow-y-auto"
        align="start"
        side="bottom"
        sideOffset={4}
      >
        <DropdownMenuItem asChild>
          <Link
            className="flex items-center gap-2 cursor-pointer"
            href="/"
            onClick={() => isMobile && setOpenMobile(false)}
          >
            <LayoutDashboard className="size-4" />
            {t("view_dashboard")}
          </Link>
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuLabel>{t("facilities")}</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {facilities.map((facility, index) => (
          <DropdownMenuItem
            key={index}
            asChild
            className={cn(
              "gap-2 p-2",
              facility.id === selectedFacility?.id &&
                "bg-neutral-100 font-medium text-neutral-950 focus:bg-neutral-200 focus:text-neutral-950",
            )}
          >
            <Link
              href={`/facility/${facility.id}/overview`}
              aria-current={
                facility.id === selectedFacility?.id ? "true" : undefined
              }
              onClick={() => isMobile && setOpenMobile(false)}
            >
              <div className="flex size-6 items-center justify-center rounded-sm border border-neutral-200 shrink-0">
                <Hospital className="size-4 shrink-0 text-current" />
              </div>
              {facility.name}
            </Link>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
import { expect, test } from "@playwright/test";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

test.describe("Sidebar Facility Switcher - Search", () => {
  test("should filter facilities in the switcher dropdown", async ({
    page,
  }) => {
    await page.goto(`/facility/${getFacilityId()}/overview`);

    //switcher
    await page.getByRole("button", { name: "Select Facility" }).click();
    await expect(page.getByText(/view dashboard/i)).toBeVisible();
    await expect(page.getByText(/Facilities/i)).toBeVisible();

    const searchInput = page.getByPlaceholder(/search/i);

    const isSearchVisible = await searchInput.isVisible().catch(() => false);
    if (!isSearchVisible) {
      test.skip();
      return;
    }

    await test.step("Search for a facility FACILITY WITH PATIENTS", async () => {
      const facilityName = "FACILITY WITH PATIENTS";

      await searchInput.fill(facilityName);

      // Verify matching facility is still visible
      await expect(
        page.getByRole("menuitem").filter({ hasText: facilityName }),
      ).toBeVisible();
    });

    await test.step("Show empty state for non-matching search", async () => {
      await searchInput.fill("zzz_nonexistent_facility_xyz");
      await expect(page.getByText(/no facilities found/i)).toBeVisible();

      // Ensure more than one facility menuitem is shown after clearing search
      await searchInput.clear();
      const facilities = await page.getByRole("menuitem").all();
      expect(facilities.length).toBeGreaterThan(1);
    });
  });
});

