              onClick={(e) => e.stopPropagation()}
              onKeyDown={(e) => e.stopPropagation()}
            />
          </div>
        )}
        {filteredFacilities.length === 0 ? (
          <div className="px-2 py-4 text-center text-sm text-gray-500">
            {t("no_facilities_found")}
          </div>
        ) : (
