import {
  DefaultError,
  MutateOptions,
  useQueryClient,
} from "@tanstack/react-query";

import { BatchRequestResponse } from "@/types/base/batch/batch";
import {
  DispenseOrderRead,
  DispenseOrderStatus,
} from "@/types/emr/dispenseOrder/dispenseOrder";
import dispenseOrderApi from "@/types/emr/dispenseOrder/dispenseOrderApi";
import {
