 *  buffer})` use. */
function tinyFilePayloads(
  count: number,
): { name: string; mimeType: string; buffer: Buffer }[] {
  return Array.from({ length: count }, (_, index) => ({
    name: `tiny-${index}.txt`,
    mimeType: "text/plain",
    buffer: Buffer.from(`tiny file ${index}`),
  }));
